
import type { DeliveryZoneConfiguration } from './DeliveryZoneConfiguration.js';

export type DeliveryZone = { /** Current geographic eligibility conditions. */ "configuration": DeliveryZoneConfiguration; /** Time the zone was created. Format: date-time. */ "created_at": string; /** Immutable revision used for new quotes. */ "current_delivery_zone_revision_id": string; /** Stable delivery zone ID. */ "delivery_zone_id": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing zone name. */ "name": string; /** Current zone lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked" | (string & {}); /** Time the zone last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for zone writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
